param([string]$OutDir=(Join-Path $PSScriptRoot 'out'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$previous=Get-Content -Raw (Join-Path $PSScriptRoot '../r5-003/out/build.json')|ConvertFrom-Json
$OutDir=[IO.Path]::GetFullPath($OutDir);New-Item -ItemType Directory -Path $OutDir -Force|Out-Null
$compiler=Join-Path $previous.msvc 'bin/Hostx64/x64/cl.exe';$oldPath=$env:PATH;$oldInclude=$env:INCLUDE;$oldLib=$env:LIB
try {
 $env:PATH="$(Split-Path $compiler);$oldPath";$env:INCLUDE=@((Join-Path $previous.msvc 'include'),(Join-Path $previous.sdk "Include/$($previous.sdkVersion)/ucrt"),(Join-Path $previous.sdk "Include/$($previous.sdkVersion)/shared"),(Join-Path $previous.sdk "Include/$($previous.sdkVersion)/um"))-join ';';$env:LIB=@((Join-Path $previous.msvc 'lib/x64'),(Join-Path $previous.sdk "Lib/$($previous.sdkVersion)/ucrt/x64"),(Join-Path $previous.sdk "Lib/$($previous.sdkVersion)/um/x64"))-join ';'
 $sources=@('image-contract.hpp','app-registration.hpp','relocation.hpp','apps/fixture.cpp','apps/recorder.cpp','apps/traps.asm','../r5-002/runtime/execution.cpp','../r5-002/runtime/execution.hpp','../r5-002/clients/host.hpp','../r5-003/runtime/store.cpp','../r5-004a/abort-helper.cpp','../r5-004a/abort-runtime.cpp','../r5-004a/abort-channel.hpp','../r5-004a/abort-host.hpp','../r5-004a/clients/run.hpp','clients/fixture-client.cpp','clients/recorder-client.cpp','faults.hpp','prepare-apps.py','build.ps1')
 $sourceInputs=@($sources|ForEach-Object{[ordered]@{file=$_;sha256=(Get-FileHash (Join-Path $PSScriptRoot $_)).Hash.ToLowerInvariant()}})
 $sha=[Security.Cryptography.SHA256]::Create();try{$buildId=[Convert]::ToHexString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes(($sourceInputs.sha256 -join '')))).ToLowerInvariant()}finally{$sha.Dispose()}
 [IO.File]::WriteAllText((Join-Path $OutDir 'build_id.hpp'),"#pragma once`n#define R305_BUILD_ID `"$buildId`"`n",[Text.Encoding]::ASCII)
 $reuse=@();foreach($name in @('helper.exe','runtime304.dll')){$source=Join-Path $PSScriptRoot "../r5-004a/out/$name";$target=Join-Path $OutDir $name;Copy-Item -LiteralPath $source -Destination $target -Force;$hash=(Get-FileHash $source).Hash;if($hash -ne (Get-FileHash $target).Hash){throw 'Reuse byte mismatch'};$reuse+=[ordered]@{file=$name;source=$source;sha256=$hash.ToLowerInvariant();identical=$true}}
 $reuse|ConvertTo-Json|Set-Content (Join-Path $OutDir 'reuse.json') -Encoding utf8
 $common=@('/nologo','/std:c++20','/EHsc','/W4','/WX','/O2','/MT','/GS','/guard:cf','/Gy','/utf-8','/DUNICODE','/D_UNICODE','/D_WIN32_WINNT=0x0A00','/DFOCUS_VIEWS_CRASH_EXPERIMENT','/DFOCUS_VIEWS_STOPPOINT_EXPERIMENT','/DFOCUS_VIEWS_IMAGE_RELOCATION_EXPERIMENT',"/I$OutDir",'/Zi',"/Fd$OutDir/compiler.pdb")
 $units=[ordered]@{manager='../r5-004/manager_main.cpp';controller='../r5-004/controller.cpp';fixture_client='clients/fixture-client.cpp';recorder_client='clients/recorder-client.cpp';store='../r5-003/runtime/store.cpp';native='../r5-001a/runtime/native.cpp';codec='../r5-001a/runtime/codec.cpp';execution='../r5-002/runtime/execution.cpp';fixture='apps/fixture.cpp';recorder='apps/recorder.cpp';fixture_io='../r5-001a/app/application.cpp';fixture_main='../r5-001a/app/fixture_main.cpp';recorder_io='../r5-002/recorder/io.cpp';abort_helper='../r5-004a/abort-helper.cpp';abort_runtime='../r5-004a/abort-runtime.cpp'}
 foreach($name in $units.Keys){$flags=$common;if($name -in @('fixture','recorder')){$flags=@($common|Where-Object {$_ -ne '/O2'})+@('/Od','/Ob0','/FAs',"/Fa$OutDir/$name.asm")}; & $compiler @flags /c "/Fo$OutDir/$name.obj" (Join-Path $PSScriptRoot $units[$name]);if($LASTEXITCODE -ne 0){throw "Compile failed $name"}}
 & (Join-Path $previous.msvc 'bin/Hostx64/x64/ml64.exe') /nologo /c "/Fo$OutDir/traps.obj" (Join-Path $PSScriptRoot 'apps/traps.asm');if($LASTEXITCODE -ne 0){throw 'Assembler failed'}
 & (Join-Path $previous.msvc 'bin/Hostx64/x64/lib.exe') /nologo "/OUT:$OutDir/kernel.lib" "$OutDir/native.obj" "$OutDir/codec.obj" "$OutDir/execution.obj";if($LASTEXITCODE -ne 0){throw 'Archive failed'}
 $libraries=@('user32.lib','gdi32.lib','ole32.lib','windowscodecs.lib','bcrypt.lib','imm32.lib','advapi32.lib')
 foreach($name in @('manager','controller','fixture_client','recorder_client','fixture','recorder','abort_helper','abort_runtime')){
  $dll=$name -in @('fixture_client','recorder_client','abort_runtime');$target=switch($name){'abort_helper'{'abort-helper.exe'}'abort_runtime'{'abort-runtime.dll'}'fixture_client'{'fixture-client.dll'}'recorder_client'{'recorder-client.dll'}'recorder'{'second.exe'}default{"$name.exe"}}
  $objects=@("$OutDir/$name.obj");if($name -in @('manager','controller','fixture_client','recorder_client')){$objects+=@("$OutDir/store.obj","$OutDir/kernel.lib")}elseif($name -in @('fixture','recorder')){$objects+=@("$OutDir/traps.obj",(Join-Path $PSScriptRoot '../r5-001a/out/target.lib'));if($name -eq 'fixture'){$objects+=@("$OutDir/fixture_io.obj","$OutDir/fixture_main.obj")}else{$objects+="$OutDir/recorder_io.obj"}}
  if($name -in @('recorder','abort_helper','abort_runtime')){$objects+="$OutDir/native.obj"}
  $link=@('/nologo');if($dll){$link+='/LD'};$link+=$objects;$link+=$libraries;$link+=@("/Fe$OutDir/$target",'/link','/INCREMENTAL:NO','/DYNAMICBASE','/NXCOMPAT','/CETCOMPAT','/guard:cf','/DEBUG:FULL');& $compiler @link;if($LASTEXITCODE -ne 0){throw "Link failed $name"}
 }
 [ordered]@{time=(Get-Date -Format o);sourceHead=(& git -C $PSScriptRoot rev-parse HEAD);system=[Environment]::OSVersion.VersionString;msvc=$previous.msvc;sdk=$previous.sdk;sdkVersion=$previous.sdkVersion;compiler=(Get-Item $compiler).VersionInfo.FileVersion;security='/GS /guard:cf /CETCOMPAT /DYNAMICBASE';buildId=$buildId;sourceInputs=$sourceInputs;binaries=@(Get-ChildItem $OutDir -File|Where-Object Extension -in @('.exe','.dll','.lib')|ForEach-Object{[ordered]@{file=$_.Name;sha256=(Get-FileHash $_.FullName).Hash.ToLowerInvariant()}})}|ConvertTo-Json -Depth 7|Set-Content (Join-Path $OutDir 'build.json') -Encoding utf8
 Write-Output 'R5_004B_BUILD_OK'
}finally{$env:PATH=$oldPath;$env:INCLUDE=$oldInclude;$env:LIB=$oldLib}
